import { getErrorCategory, useDownloadMetrics } from './useDownloadMetrics';

jest.mock('@proton/metrics', () => ({
    drive_download_success_rate_total: {
        increment: jest.fn(),
    },
    drive_download_errors_total: {
        increment: jest.fn(),
    },
    drive_download_erroring_users_total: {
        increment: jest.fn(),
    },
}));

jest.mock('../../_shares/useSharesState', () => ({
    __esModule: true,
    default: jest.fn(),
}));

const mockUseShareState = jest.mocked(useSharesState);

describe('getErrorCategory', () => {
    const testCases = [
        { state: TransferState.Error, error: { status: 503 }, expected: 'server_error', desc: 'unreachable error' },
        {
            state: TransferState.Error,
            error: { name: 'TimeoutError' },
            expected: 'server_error',
            desc: 'timeout error',
        },
        {
            state: TransferState.Error,
            error: { name: 'OfflineError' },
            expected: 'network_error',
            desc: 'offline error',
        },
        {
            state: TransferState.Error,
            error: { name: 'NetworkError' },
            expected: 'network_error',
            desc: 'network error',
        },
        { state: TransferState.NetworkError, error: {}, expected: 'network_error', desc: 'NetworkError state' },
        {
            state: TransferState.Error,
            error: { statusCode: 429 },
            expected: 'rate_limited',
            desc: 'rate limited error',
        },
        { state: TransferState.Error, error: { statusCode: 400 }, expected: '4xx', desc: '4xx error' },
        { state: TransferState.Error, error: { statusCode: 500 }, expected: '5xx', desc: '5xx error' },
        { state: TransferState.Error, error: {}, expected: 'unknown', desc: 'unknown error' },
    ];

    testCases.forEach(({ state, error, expected, desc }) => {
        it(`should return ${expected} for ${desc}`, () => {
            expect(getErrorCategory(state, error)).toBe(expected);
        });
    });
});

describe('useDownloadMetrics', () => {
    const mockGetShare = jest.fn();

    beforeEach(() => {
        jest.clearAllMocks();
        mockUseShareState.mockReturnValue({ getShare: mockGetShare } as any);
    });

    it('should observe downloads and update metrics for successful downloads', () => {
        mockGetShare.mockReturnValue({ type: ShareType.default });

        const { result } = renderHook(() => useDownloadMetrics('download'));

        const testDownloads = [
            {
                id: '1',
                state: TransferState.Done,
                links: [{ shareId: 'share1' }],
                error: null,
            },
        ] as unknown as Download[];

        act(() => {
            result.current.observe(testDownloads);
        });

        expect(metrics.drive_download_success_rate_total.increment).toHaveBeenCalledWith({
            status: 'success',
            retry: 'false',
            shareType: 'main',
        });
    });

    it('should observe downloads and update metrics for failed downloads', () => {
        mockGetShare.mockReturnValue({ type: ShareType.default });

        const { result } = renderHook(() => useDownloadMetrics('download'));

        const testDownloads: Download[] = [
            {
                id: '2',
                state: TransferState.Error,
                links: [{ shareId: 'share2' }],
                error: { statusCode: 500 },
            },
        ] as unknown as Download[];

        act(() => {
            result.current.observe(testDownloads);
        });

        expect(metrics.drive_download_success_rate_total.increment).toHaveBeenCalledWith({
            status: 'failure',
            retry: 'false',
            shareType: 'main',
        });

        expect(metrics.drive_download_errors_total.increment).toHaveBeenCalledWith({
            type: '5xx',
            initiator: 'download',
            shareType: 'main',
        });
    });

    it('should observe downloads and update metrics correctly for retried downloads', () => {
        mockGetShare.mockReturnValue({ type: ShareType.default });

        const { result } = renderHook(() => useDownloadMetrics('download'));

        const testDownloads: Download[] = [
            {
                id: '2',
                state: TransferState.Error,
                links: [{ shareId: 'share2' }],
                error: { statusCode: 500 },
            },
        ] as unknown as Download[];

        act(() => {
            result.current.observe(testDownloads);
        });

        expect(metrics.drive_download_success_rate_total.increment).toHaveBeenCalledWith({
            status: 'failure',
            retry: 'false',
            shareType: 'main',
        });

        expect(metrics.drive_download_errors_total.increment).toHaveBeenCalledWith({
            type: '5xx',
            initiator: 'download',
            shareType: 'main',
        });

        act(() => {
            const testDownloadsDone: Download[] = [
                {
                    id: '2',
                    state: TransferState.Done,
                    links: [{ shareId: 'share2' }],
                    error: null,
                    retries: 1,
                },
            ] as unknown as Download[];
            result.current.observe(testDownloadsDone);
        });

        expect(metrics.drive_download_success_rate_total.increment).toHaveBeenCalledWith({
            status: 'success',
            retry: 'true',
            shareType: 'main',
        });
    });

    it('should not process the same download twice', () => {
        mockGetShare.mockReturnValue({ type: ShareType.default });

        const { result } = renderHook(() => useDownloadMetrics('download'));

        const testDownload: Download = {
            id: '3',
            state: TransferState.Done,
            links: [{ shareId: 'share3' }],
            error: null,
        } as unknown as Download;

        act(() => {
            result.current.observe([testDownload]);
        });

        act(() => {
            result.current.observe([testDownload]);
        });

        expect(metrics.drive_download_success_rate_total.increment).toHaveBeenCalledTimes(1);
    });

    it('should not handle multiple LinkDownload in a download', () => {
        mockGetShare.mockReturnValueOnce({ type: ShareType.default });

        const { result } = renderHook(() => useDownloadMetrics('download'));

        const testDownload = {
            id: '4',
            state: TransferState.Done,
            links: [{ shareId: 'share4a' }, { shareId: 'share4b' }],
            error: null,
        } as unknown as Download;

        act(() => {
            result.current.observe([testDownload]);
        });

        expect(metrics.drive_download_success_rate_total.increment).toHaveBeenCalledTimes(1);
        expect(metrics.drive_download_success_rate_total.increment).toHaveBeenNthCalledWith(1, {
            status: 'success',
            retry: 'false',
            shareType: 'main',
        });
    });

    it('should handle different error states', () => {
        mockGetShare.mockReturnValue({ type: ShareType.default });

        const { result } = renderHook(() => useDownloadMetrics('download'));

        const testDownloads: Download[] = [
            {
                id: '5',
                state: TransferState.NetworkError,
                links: [{ shareId: 'share5' }],
                error: { isNetwork: true },
            },
            {
                id: '6',
                state: TransferState.Error,
                links: [{ shareId: 'share6' }],
                error: null,
            },
        ] as unknown as Download[];

        act(() => {
            result.current.observe(testDownloads);
        });

        expect(metrics.drive_download_errors_total.increment).toHaveBeenCalledTimes(2);
        expect(metrics.drive_download_errors_total.increment).toHaveBeenCalledWith({
            type: 'network_error',
            initiator: 'download',
            shareType: 'main',
        });
        expect(metrics.drive_download_errors_total.increment).toHaveBeenCalledWith({
            type: 'unknown',
            initiator: 'download',
            shareType: 'main',
        });
    });

    it('should only report failed users every 5min', () => {
        jest.useFakeTimers().setSystemTime(new Date('2020-01-01 10:00:00'));
        mockGetShare.mockReturnValue({ type: ShareType.default });
        const { result } = renderHook(() => useDownloadMetrics('download'));

        act(() => {
            result.current.observe([
                {
                    id: '2',
                    state: TransferState.Error,
                    links: [{ shareId: 'share2' }],
                    error: { statusCode: 500 },
                },
            ] as unknown as Download[]);
        });
        expect(metrics.drive_download_erroring_users_total.increment).toHaveBeenCalledWith({
            plan: 'unknown',
            shareType: 'main',
        });

        // 1 min passed
        jest.useFakeTimers().setSystemTime(new Date('2020-01-01 10:01:00'));
        act(() => {
            result.current.observe([
                {
                    id: '234',
                    state: TransferState.Error,
                    links: [{ shareId: 'share234' }],
                    error: { statusCode: 500 },
                },
            ] as unknown as Download[]);
        });
        expect(metrics.drive_download_erroring_users_total.increment).toHaveBeenCalledTimes(1);

import type { VERIFICATION_STATUS } from '@proton/crypto';

import type { TransferMeta, TransferState } from '../../../components/TransferManager/transfer';
import type { LinkDownload } from '../interface';

export interface Download {
    // ID of the download for referencing (such as pausing and so on).
    id: string;

    links: LinkDownload[];
    meta: TransferMeta; // To be compatible with Download of TransferManager.

    startDate: Date;
    state: TransferState;
    resumeState?: TransferState; // resumeState is set only when state is paused.
    error?: Error;
    // Signature link and status is set only when state is set to SignatureIssue.
    // Note that download can be of several links (for example the whole folder)
    // and only one of them can have signature issue. We need to know which one
    // exactly has the issue.
    signatureIssueLink?: LinkDownload;
    signatureStatus?: VERIFICATION_STATUS;
    scanIssueError?: Error;
    options?: { virusScan?: boolean };
    retries: number;
}

export interface DownloadProgresses {
    [downloadId: string]: {
        progress: number;
        links: DownloadLinksProgresses;
    };
}
export interface DownloadLinksProgresses {
    [linkId: string]: {
        total?: number;
        progress: number;
    };
}

export type UpdateFilter = string | ((params: UpdateCallbackParams) => boolean);
export type UpdateState = TransferState | ((params: UpdateCallbackParams) => TransferState);
export type UpdateCallback = (params: UpdateCallbackParams) => void;
export type UpdateData = {
    size?: number;
    error?: Error;
    signatureIssueLink?: LinkDownload;
    signatureStatus?: VERIFICATION_STATUS;
    scanIssueError?: Error;
    retry?: boolean;
};
export type UpdateCallbackParams = {
    id: string;
    state: TransferState;
    resumeState?: TransferState;
};

export class DownloadUserError extends Error {
    constructor(message: string) {
        super(message);
        this.name = 'DownloadUserError';
    }
}
import { WritableStream } from 'web-streams-polyfill';

import { isIos, isSafari } from '@proton/shared/lib/helpers/browser';
import { stripLeadingAndTrailingSlash } from '@proton/shared/lib/helpers/string';
import { PUBLIC_PATH } from '@proton/shared/lib/webpack.constants';

import type { TransferMeta } from '../../../components/TransferManager/transfer';

let workerWakeupInterval: ReturnType<typeof setInterval>;

/**
 * Safari and Edge don't support returning stream as a response.
 * Safari - has everything but fails to stream a response from SW.
 * Edge - doesn't support ReadableStream() constructor, but supports it in chromium version.
 * IOS - forces all browsers to use webkit, so same problems as safari in all browsers.
 * For them download is done in-memory using blob response.
 */
export const isUnsupported = () => {
    /* TODO: To be removed after test DRVWEB-4375 */
    if (typeof window !== 'undefined') {
        const isSWForSafariEnabled = 'isSWForSafariEnabled' in window && window.isSWForSafariEnabled;
        if (isSWForSafariEnabled) {
            return !('serviceWorker' in navigator);
        }
    }
    // Original
    return !('serviceWorker' in navigator) || isSafari() || isIos();
};

// createDownloadIframe opens download URL created in service worker to
// initialize the download in the browser. The response has headers to
// act as the download. See DownloadServiceWorker for more info.
function createDownloadIframe(src: string) {
    const iframe = document.createElement('iframe');
    iframe.hidden = true;
    iframe.src = src;
    iframe.name = 'iframe';
    document.body.appendChild(iframe);
    return iframe;
}

async function wakeUpServiceWorker(retry = true) {
    const worker = navigator.serviceWorker.controller;

    if (worker) {
        worker.postMessage({ action: 'ping' });
    } else {
        const url = [
            document.location.href.substring(0, document.location.href.indexOf('/')),
            stripLeadingAndTrailingSlash(PUBLIC_PATH),
            'sw/ping',
        ]
            .filter(Boolean)
            .join('/');
        const res = await fetch(url);
        const body = await res.text();
        if (!res.ok || body !== 'pong') {
            if (!retry) {
                throw new Error('Download worker is dead');
            }
            console.warn('Download worker is dead, retrying registration');
            await initDownloadSW();
            await wakeUpServiceWorker(false);
        }
    }
    return worker as ServiceWorker;
}

function serviceWorkerKeepAlive() {
    clearInterval(workerWakeupInterval);
    workerWakeupInterval = setInterval(() => {
        wakeUpServiceWorker().catch(() => clearInterval(workerWakeupInterval));
    }, 10000);
}

export async function initDownloadSW() {
    if (isUnsupported()) {
        throw new Error('Saving file via download is unsupported by this browser');
    }

    await navigator.serviceWorker
        .register(
            /* webpackChunkName: "downloadSW" */
            new URL('./downloadSW', import.meta.url),
            {
                scope: `/${stripLeadingAndTrailingSlash(PUBLIC_PATH)}`,
            }
        )
        .then((registration) => {
            // We do not cache manifest for local server or this can cause HMR to infinite reload
            if (!window.location.host.includes('proton.local')) {
                /*
                Upon sending cache_assets action we fetch all assets using the Service Worker
                Diagram can be seen here using the mermaid diagram file applications/drive/src/app/store/_downloads/fileSaver/mermaid-cache-assets-diagram.json to be uploaded on https://mermaid.live/
            */
                if (registration.active?.state === 'activated') {
                    registration.active.postMessage({ action: 'cache_assets' });
                } else if (registration.installing) {
                    registration.installing.addEventListener('statechange', () => {
                        if (registration.active?.state === 'activated') {
                            registration.active.postMessage({ action: 'cache_assets' });
                        }
                    });
                }
            }
        });

    serviceWorkerKeepAlive();
}

/**
 * Opens download stream into service worker. Use abort signal when pipeTo can't close the download stream.
 */
export async function openDownloadStream(
    meta: TransferMeta,
    { onCancel, abortSignal }: { onCancel: () => void; abortSignal?: AbortSignal }
) {
    const channel = new MessageChannel();
    const stream = new WritableStream({
        write(block: Uint8Array) {
            channel.port1.postMessage({ action: 'download_chunk', payload: block });
        },
        close() {
            channel.port1.postMessage({ action: 'end' });
        },
        abort(reason) {
            channel.port1.postMessage({ action: 'abort', reason: String(reason) });
        },
    });

    if (abortSignal) {
        abortSignal.addEventListener('abort', () => {
            channel.port1.postMessage({ action: 'abort', reason: 'Download stream aborted' });
        });
    }

    const worker = await wakeUpServiceWorker();

    // Channel to stream file contents through
    channel.port1.onmessage = ({ data }) => {
        if (data?.action === 'download_canceled') {
            onCancel();
        } else if (data?.action === 'download_started') {
            createDownloadIframe(data.payload);
        }
    };
    worker.postMessage({ action: 'start_download', payload: meta }, [channel.port2]);

    return stream;
}

