const metricRegexp = /^[a-zA-Z]+(?:_[a-zA-Z0-9]+)*$/;

function validateMetricName(name: string) {
    return metricRegexp.test(name);
}

abstract class Metric<D extends MetricSchema> {
    private name: string;

    private version: MetricVersions;

