        return this.saveViaDownload(stream, meta, log);
    }

    isUsingBlobFallback() {
        return this.useBlobFallback;
    }

    isFileTooBig(size: number) {
        return selectMechanismForDownload(size) === 'memory_fallback' && size >= MEMORY_DOWNLOAD_LIMIT;
    }
}

const fileSaver = new FileSaver();

export function selectMechanismForDownload(size?: number): 'memory' | 'sw' | 'memory_fallback' {
    if (size !== undefined && size < MEMORY_DOWNLOAD_LIMIT) {
        return 'memory';
    }
    return isUnsupported() || fileSaver.isUsingBlobFallback() ? 'memory_fallback' : 'sw';
}

export default fileSaver;
